import{_ as o,o as e,c as r,a4 as a}from"./chunks/framework.bruR1JhL.js";const c=JSON.parse('{"title":"Crop, rotate, collage & capture","description":"Crop an image to a box, circle or aspect ratio, rotate or flip many images at once, put photos together in a collage, and turn a web page or HTML into a picture.","frontmatter":{"title":"Crop, rotate, collage & capture","description":"Crop an image to a box, circle or aspect ratio, rotate or flip many images at once, put photos together in a collage, and turn a web page or HTML into a picture."},"headers":[],"relativePath":"docs/img-layout.md","filePath":"docs/img-layout.md","lastUpdated":1795509372000}'),s={name:"docs/img-layout.md"};function n(i,t,d,l,h,g){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="crop-rotate-collage-capture" tabindex="-1">Crop, rotate, collage &amp; capture <a class="header-anchor" href="#crop-rotate-collage-capture" aria-label="Permalink to &quot;Crop, rotate, collage &amp; capture&quot;">​</a></h1><p>These tools change the frame of a picture, or make a new one from a web page. They read JPG, PNG, WebP, HEIC/HEIF (iPhone), AVIF, GIF, BMP, TIFF and ICO, and save JPG, PNG, WebP or AVIF, or keep the original&#39;s format (HTML to Image saves PNG, JPG or WebP). Every tool saves a new file and never changes the original. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the Explorer, the Preview pane and the Saved card.</p><ul><li><strong>Crop Image</strong> works on one image. It shares the open image with Upscale Image, Remove background, Blur face and the Photo editor, so you can switch between them without opening it again.</li><li><strong>Rotate Image</strong> works on a list. Add images with <strong>Add images…</strong> or by dragging them from the Explorer, and remove them with the × on each row or <strong>Clear list</strong>. It saves next to each image, or in a folder you choose.</li><li><strong>Photo collage</strong> puts a list of photos together in one new picture.</li><li><strong>HTML to Image</strong> makes a new picture from a web address, an HTML file or HTML code.</li></ul><h2 id="crop-image" tabindex="-1">Crop Image <a class="header-anchor" href="#crop-image" aria-label="Permalink to &quot;Crop Image&quot;">​</a></h2><p>Trims the edges of an image, or frames it to an exact aspect ratio. You can also crop to a circle or oval, with a transparent outside.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li><p>In the <strong>Images</strong> section, open the <strong>Frame</strong> tab and choose <strong>Crop Image</strong>.</p></li><li><p>Open an image: click <strong>Open image…</strong>, drag one from the Explorer, or click <strong>Use</strong> followed by the name of the image selected in the Explorer. You can also right-click an image in the Explorer and choose <strong>Crop image</strong>.</p></li><li><p>Set the crop box on the picture:</p><ul><li>Drag inside the box to move it.</li><li>Drag a corner or an edge to resize it.</li><li>Drag outside the box to draw a new one.</li></ul><p>The box shows its size in pixels and rule-of-thirds guides.</p></li><li><p>If you want a fixed shape, pick an <strong>Aspect ratio</strong>, or type exact values under <strong>Area (pixels)</strong>.</p></li><li><p>Choose the <strong>Shape</strong>, <strong>Format</strong> and <strong>Quality</strong>.</p></li><li><p>Click <strong>Crop and save…</strong> and choose a name and folder in the Save dialog.</p></li></ol><p>To work on another image, use <strong>Change…</strong> in the bar above the picture, or <strong>Close</strong> it.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Aspect ratio</strong></td><td><strong>Free</strong>, <strong>Original</strong> (the image&#39;s own proportions), <strong>1:1</strong>, <strong>4:3</strong>, <strong>3:4</strong>, <strong>16:9</strong>, <strong>9:16</strong>, <strong>3:2</strong>, <strong>2:3</strong>, <strong>5:4</strong> or <strong>4:5</strong>. Picking a ratio resets the box to the largest centred box with that ratio.</td><td>Free</td></tr><tr><td><strong>Area (pixels)</strong></td><td><strong>X</strong>, <strong>Y</strong>, <strong>Width</strong> and <strong>Height</strong> of the box. With a fixed ratio, changing the width changes the height to match, and the other way round. The box always stays inside the image.</td><td>The middle 80% of the image</td></tr><tr><td><strong>Shape</strong></td><td><strong>Rectangle</strong>, or <strong>Circle / oval</strong>: only the oval inside the box is kept, and the outside becomes transparent. Use <strong>1:1</strong> for a perfect circle.</td><td>Rectangle</td></tr><tr><td><strong>Format</strong></td><td><strong>Same as the original</strong>, <strong>JPG</strong>, <strong>PNG</strong>, <strong>WebP</strong> or <strong>AVIF</strong>.</td><td>Same as the original</td></tr><tr><td><strong>Quality</strong></td><td>10 to 100. Hidden when the file is saved as PNG.</td><td>92</td></tr></tbody></table><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The Save dialog suggests the original&#39;s name with <code>_cropped</code> added, in the same folder, for example <code>portrait_cropped.jpg</code>.</li><li>With a fixed aspect ratio, the box has corner handles only, so it keeps its shape.</li><li>JPG can&#39;t store transparency, so a <strong>Circle / oval</strong> crop is saved as PNG unless you choose WebP or AVIF (or the original already is PNG, WebP or AVIF and you keep its format). This happens even if you choose JPG.</li><li>Pixel positions refer to the image as you see it, upright.</li><li><strong>Same as the original</strong> saves HEIC/HEIF photos as JPG and ICO files as PNG.</li><li>The camera details and the colour profile are kept.</li><li>In the <strong>Saved</strong> card, <strong>Keep editing this file</strong> opens the cropped copy, so you can carry on with it in this tool or another image tool.</li></ul><h2 id="rotate-image" tabindex="-1">Rotate Image <a class="header-anchor" href="#rotate-image" aria-label="Permalink to &quot;Rotate Image&quot;">​</a></h2><p>Turns images by 90°, 180° or 270°, or mirrors them. Set each image on its own, or change all of them at once.</p><h3 id="how-to-use-it-1" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>In the <strong>Images</strong> section, open the <strong>Frame</strong> tab and choose <strong>Rotate Image</strong>.</li><li>Click <strong>Add images…</strong>, or drag images from the Explorer onto the list.</li><li>Turn or flip each image with the buttons on its row: <strong>Rotate left</strong>, <strong>Rotate right</strong>, <strong>Flip horizontally</strong> (⇋) and <strong>Flip vertically</strong> (⇵). The thumbnail shows the result.</li><li>Or use the buttons after <strong>All images:</strong> to change every image in the list: <strong>Left</strong>, <strong>Right</strong>, <strong>180°</strong>, <strong>Flip horizontally</strong> and <strong>Flip vertically</strong>. <strong>Reset</strong> undoes all turns and flips.</li><li>Choose the <strong>Format</strong> and <strong>Quality</strong>, and where to save.</li><li>Click <strong>Rotate and save</strong> (or <strong>Rotate and save 3 images</strong>).</li></ol><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Format</strong></td><td><strong>Same as the original</strong>, <strong>JPG</strong>, <strong>PNG</strong>, <strong>WebP</strong> or <strong>AVIF</strong>.</td><td>Same as the original</td></tr><tr><td><strong>Quality</strong></td><td>10 to 100. Used for JPG, WebP and AVIF.</td><td>95</td></tr><tr><td>Where to save</td><td><strong>Save next to each image</strong>, or <strong>Save in a folder</strong>.</td><td>Save next to each image</td></tr></tbody></table><h3 id="good-to-know-1" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-1" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Only the images you turned or flipped are saved. If you haven&#39;t changed any, the action bar says &quot;Turn or flip at least one image.&quot;</li><li>New files are named after the original with <code>_rotated</code> added, for example <code>scan_rotated.jpg</code>.</li><li>The picture is turned and then saved again, so JPG, WebP and AVIF files are re-encoded at the <strong>Quality</strong> you set.</li><li>Photos are shown upright first (the camera&#39;s rotation flag is applied), so turns are relative to what you see. The saved file is upright and has no rotation flag.</li><li>The camera details and the colour profile are kept.</li><li>Animated GIFs and multi-page TIFFs are saved as a single picture: only the first frame or page is kept.</li></ul><h2 id="photo-collage" tabindex="-1">Photo collage <a class="header-anchor" href="#photo-collage" aria-label="Permalink to &quot;Photo collage&quot;">​</a></h2><p>Puts several photos together on one canvas: in a grid, in a mosaic that keeps every photo whole, or with one photo large and the others beside it.</p><h3 id="how-to-use-it-2" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-2" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>In the <strong>Images</strong> section, open the <strong>Frame</strong> tab and choose <strong>Photo collage</strong>.</li><li>Add at least two photos: click <strong>Add images…</strong>, or drag them from the Explorer onto the list. You can also right-click an image in the Explorer and choose <strong>Add to collage</strong>.</li><li>Put them in order with the ↑ and ↓ buttons on each row, or click <strong>Shuffle the photos</strong>. The order of the list is the order in the collage.</li><li>Pick a layout: <strong>Grid</strong>, <strong>Mosaic</strong> or <strong>Featured</strong>, and adjust its options. The preview updates as you go.</li><li>Set the spacing, border, corners and background, and the <strong>Width</strong>, <strong>Format</strong> and <strong>Quality</strong> under <strong>Output</strong>.</li><li>Click <strong>Save collage…</strong> and choose a name and folder in the Save dialog.</li></ol><h3 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layout</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Grid</strong></td><td>Rows and columns of equal cells. <strong>Columns</strong> is <strong>Automatic</strong> (the number that crops your photos least) or 1 to 8. If the last row has fewer photos, they share its full width.</td></tr><tr><td><strong>Mosaic</strong></td><td>Rows of photos at their own shape, each row scaled to the full width, so nothing is cropped. <strong>Photos per row</strong> sets roughly how many fit in a row. The collage&#39;s height follows from the photos.</td></tr><tr><td><strong>Featured</strong></td><td>The first photo in the list is large, on the <strong>Left</strong>, <strong>Top</strong>, <strong>Right</strong> or <strong>Bottom</strong>; the others share the rest in a grid. <strong>Big photo</strong> sets how much of the space it takes.</td></tr></tbody></table><h3 id="options-2" tabindex="-1">Options <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Shape</strong></td><td>Square (1:1), Portrait (4:5), Landscape (3:2), Wide (16:9), Story (9:16), A4 portrait or A4 landscape. Not used by Mosaic.</td><td>Square</td></tr><tr><td><strong>Fill (crop)</strong> / <strong>Whole photo</strong></td><td>Fill each cell, cropping what doesn&#39;t fit (from the centre), or show the whole photo with the background around it. Not used by Mosaic.</td><td>Fill</td></tr><tr><td><strong>Spacing</strong></td><td>The gap between photos, as a share of the width.</td><td>1%</td></tr><tr><td><strong>Border</strong></td><td>The space around the edge, as a share of the width.</td><td>2%</td></tr><tr><td><strong>Rounded corners</strong></td><td>Rounds each photo&#39;s corners.</td><td>0%</td></tr><tr><td><strong>Background</strong></td><td>The colour behind the photos, or <strong>Transparent</strong>.</td><td>White</td></tr><tr><td><strong>Width</strong></td><td>1200, 2400, 3600 or 4800 pixels; the height follows from the shape (or, for Mosaic, from the photos).</td><td>2400 px</td></tr><tr><td><strong>Format</strong>, <strong>Quality</strong></td><td>JPG, PNG, WebP or AVIF; quality from 10 to 100 for JPG, WebP and AVIF.</td><td>JPG, 90</td></tr></tbody></table><h3 id="good-to-know-2" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-2" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The action bar shows the number of photos and the size of the file you&#39;ll get, in pixels.</li><li><strong>Transparent</strong> needs a format that keeps transparency, so it switches JPG to PNG. With rounded corners on a transparent background, the corners are see-through too.</li><li>Photos are shown upright first (the camera&#39;s rotation flag is applied). The collage is saved without the photos&#39; camera details or location.</li><li>The new file is named <code>collage</code> (then <code>collage (2)</code> and so on) and saved next to the first photo unless you choose another place. <strong>Keep editing this file</strong> opens it in the Photo editor, to add text, stickers or a filter.</li><li>Animated GIFs and multi-page TIFFs contribute their first frame or page.</li></ul><h2 id="html-to-image" tabindex="-1">HTML to Image <a class="header-anchor" href="#html-to-image" aria-label="Permalink to &quot;HTML to Image&quot;">​</a></h2><p>Renders a web page, an HTML file or a snippet of HTML and CSS into a PNG, JPG or WebP picture. You can capture the whole page or just the visible area, at the width of any screen.</p><h3 id="how-to-use-it-3" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-3" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>In the <strong>Images</strong> section, open the <strong>Frame</strong> tab and choose <strong>HTML to Image</strong>.</li><li>Choose the source: <ul><li><strong>Web page</strong>: type the address in the box, for example <code>example.com</code>.</li><li><strong>HTML file</strong>: click <strong>Choose an HTML file…</strong> and pick an <code>.html</code>, <code>.htm</code>, <code>.xhtml</code> or <code>.svg</code> file.</li><li><strong>HTML code</strong>: type or paste HTML in the box. It starts with a small sample you can replace.</li></ul></li><li>Set the options (see below). The action bar shows the width of the picture, for example &quot;1280px wide at 2× → 2560px&quot;.</li><li>Click <strong>Capture and save…</strong> and choose a name and folder in the Save dialog. The button says <strong>Rendering…</strong> while it works.</li><li>When it&#39;s done, the <strong>Saved</strong> card appears, with the captured picture below it.</li></ol><h3 id="options-3" tabindex="-1">Options <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Screen width</strong></td><td><strong>Desktop (1440 px)</strong>, <strong>Laptop (1280 px)</strong>, <strong>Tablet (768 px)</strong>, <strong>Phone (390 px)</strong> or <strong>Custom…</strong>. The page is laid out as on a screen this wide.</td><td>Laptop (1280 px)</td></tr><tr><td><strong>Width (px)</strong></td><td>With <strong>Custom…</strong>: any width from 320 to 3840 px.</td><td>1000</td></tr><tr><td><strong>Capture</strong></td><td><strong>The whole page</strong>, from top to bottom, or <strong>The visible area only</strong>.</td><td>The whole page</td></tr><tr><td><strong>Visible height (px)</strong></td><td>With <strong>The visible area only</strong>: the height of the screen, from 200 to 4000 px.</td><td>800</td></tr><tr><td><strong>Sharpness</strong></td><td><strong>1× (standard)</strong>, <strong>2× (retina)</strong> or <strong>3×</strong>. Multiplies the number of pixels, for sharp text on high-resolution screens.</td><td>1× (standard)</td></tr><tr><td><strong>Format</strong></td><td><strong>PNG</strong>, <strong>JPG</strong> or <strong>WebP</strong>.</td><td>PNG</td></tr><tr><td><strong>Quality</strong></td><td>10 to 100, for JPG and WebP.</td><td>90</td></tr><tr><td><strong>Wait after loading (s)</strong></td><td>Extra time to wait after the page has loaded, from 0 to 30 seconds. Useful for pages that animate or load content late.</td><td>0</td></tr><tr><td><strong>Transparent background (for snippets and pages without a background)</strong></td><td>For PNG and WebP. Areas without a background colour stay transparent instead of white.</td><td>Off</td></tr></tbody></table><h3 id="good-to-know-3" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-3" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Only <code>http://</code> and <code>https://</code> addresses work. If you leave out the start, Tilepress adds <code>https://</code>.</li><li>The page is rendered by WebView2, the engine that also draws Tilepress, in a window kept off-screen, out of sight and out of the taskbar. The page runs as it would in a browser, scripts included. Only one page is rendered at a time.</li><li>Tilepress waits up to 60 seconds for the page to load, then up to 15 seconds more for its fonts and images. For <strong>The whole page</strong>, it also scrolls through the page first so lazy-loaded pictures appear, then goes back to the top.</li><li>Widths under 600 px are rendered as on a phone.</li><li>Scroll bars are hidden in the picture.</li><li><strong>The whole page</strong> is captured up to 16,000 pixels tall (before <strong>Sharpness</strong> is applied). A longer page is cut off at that point.</li><li>Suggested names: for a web page, a name taken from the address in your Downloads folder, such as <code>example.com.png</code>; for an HTML file, the file&#39;s name with the picture&#39;s extension, in the same folder; for HTML code, <code>snippet.png</code> in your Downloads folder.</li><li>Pasted code that isn&#39;t a complete page is wrapped in one. Because it&#39;s rendered from a temporary folder, relative links to pictures or stylesheets won&#39;t find your files. Save the HTML as a file next to them and use <strong>HTML file</strong> instead.</li><li>Saved pictures contain no metadata.</li><li>If the page can&#39;t be reached, you&#39;ll see &quot;The page couldn&#39;t be loaded. Check the address and your internet connection.&quot;</li></ul><div class="warning custom-block"><p class="custom-block-title">Uses the internet</p><p>A <strong>Web page</strong> is downloaded from the internet, with everything it links to. An <strong>HTML file</strong> or <strong>HTML code</strong> can also fetch pictures, fonts or scripts from the internet if it links to them. See <a href="/tilepress/docs/privacy">Privacy</a>.</p></div><p>To turn HTML into a PDF instead, use <strong>HTML to PDF</strong> in <a href="/tilepress/docs/to-pdf">Convert to PDF</a>.</p>',40)])])}const u=o(s,[["render",n]]);export{c as __pageData,u as default};
